INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M23EBH004V863NHM3JQFEM1Q', 25.06015, 121.56477, '阿勃勒', '[23]', '[]', 3, 5, '計畫移植。「富民生態公園整建工程」移植計畫（狀態不明）。計畫書編號 7. C080。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：因配合本案工程需要辦理移植(考量樹木現植位置與工程整體設計之人行動線衝突、周邊樹冠過於密集導致生長不良。)；並藉由移植，提供樹木優於現植環境之生長空間，俾利後續生長。', 'https://pkl.gov.taipei/News_Content.aspx?n=EADA2FE1CC599432&sms=1A78AA9B70F45574&s=ACC9937C6DB0769B', '2026-09-10', NULL, 'SS0195001077', 'pkl:transplant_ACC9937C6DB0769B:0:7. C080', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M23EBH00620NQ3EMF2TG2192', 25.06018, 121.56485, '榕樹', '[3,23]', '[]', 3, 5, '計畫移除。「富民生態公園整建工程」移除計畫（審查中）。計畫書編號 C084。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：所有大分枝皆為截頂、樹皮損傷、傷口無法癒合產生腐朽、位於高度活動空間周邊。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D13E810EB14DD7D8', '2026-09-10', NULL, 'SS0195001073', 'pkl:removal_D13E810EB14DD7D8:0:C084', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
