INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW000384JNQNAC1YRFGQ', 25.03107, 121.56819, '黑板樹', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A73。日期為計畫上網日期。座標與計畫書編號 A72 相同，位置可能有誤。原因：關鍵因子：根領處有局部損傷，生長有偏向，枝葉稀疏活冠比低，曾截斷修剪影響樹形。；處理建議：根基或根領有損傷影響結構支撐，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031102', 'pkl:removal_D3BB0AD389D1F53B:0:A73', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW0003CG31WAS02PPRK6', 25.08542, 121.55193, '垂榕', '[20]', '[]', 3, 5, '計畫移植。臺北捷運環狀線北環段CF690B區段標CF694子標樹木移植計畫書（已核准）。計畫書編號 Y29-51。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：為配合台北捷運環狀線北環段Y27 站(不含),Y28 站,Y29 站,尾軌段及車站間之潛盾隧道,沿線聯絡通道各項施工需求配合辦理樹木之移植及現地保護作業。', 'https://pkl.gov.taipei/News_Content.aspx?n=EADA2FE1CC599432&sms=1A78AA9B70F45574&s=368BF9E235237B1E', '2026-09-23', NULL, 'JS0760011231', 'pkl:transplant_368BF9E235237B1E:0:Y29-51', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00048V5264112SXHQR', 25.03212, 121.56818, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A52。日期為計畫上網日期。原因：關鍵因子：主枝有空洞，等勢枝等勢幹，生長偏向，主幹有截斷樹梢枯枝，有創傷後癒合不良。；處理建議：明顯樹洞或主幹主枝明顯腐朽影響安全，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031081', 'pkl:removal_D3BB0AD389D1F53B:0:A52', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00084XXQJ5FW41CWSA', 25.03138, 121.5681, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A178。日期為計畫上網日期。原因：關鍵因子：主幹有枯朽枝幹有分裂傷，修枝的復原，無法癒合產生腐朽。；處理建議：主幹歪斜或生長偏向嚴重有影響安全之虞，癒合不良影響結構建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680063027', 'pkl:removal_D3BB0AD389D1F53B:0:A178', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
