INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW000MQJZZTHZ5Z7FNHT', 25.02922, 121.5685, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B234。日期為計畫上網日期。原因：關鍵因子：主幹斜向生長，等勢幹，接領處腫大及有切口癒合不良，樹冠受機械危害，修枝後傷口無法癒合產生腐朽。；處理建議：主幹主枝明顯腐朽影響安全，接領處腫大及有切口癒合不良，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062067', 'pkl:removal_D3BB0AD389D1F53B:0:B234', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
