INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW000X7XWN6WEC1BWBY9', 25.03144, 121.56854, '檬果', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B253。日期為計畫上網日期。座標與計畫書編號 B254 相同，位置可能有誤。原因：關鍵因子：修枝或創傷後無法癒合產生腐朽，移除枯枝等不健康部預期無法恢復良好樹型。樹型完全崩壞。；處理建議：建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680010051', 'pkl:removal_D3BB0AD389D1F53B:0:B253', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW000Z3M9GHJWB4CZN7A', 25.03236, 121.56816, '樟樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A50。日期為計畫上網日期。座標與計畫書編號 A49 相同，位置可能有誤。原因：關鍵因子：主幹損傷嚴重，修剪不當，樹勢衰弱。；處理建議：明顯樹洞或主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680010002', 'pkl:removal_D3BB0AD389D1F53B:0:A50', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW0014AX5GRRM4HVBGMK', 25.03232, 121.5685, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B89。日期為計畫上網日期。原因：關鍵因子：生長偏向，有等勢枝或等勢幹，根群出現浮根及盤根，修枝後無法癒合產生腐朽。；處理建議：根領有損傷影響結構支撐，截幹後癒合不良有影響結構，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022008', 'pkl:removal_D3BB0AD389D1F53B:0:B89', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW0017YPX50H4Z0Z8TBS', 25.02982, 121.5685, '水黃皮', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B223。日期為計畫上網日期。原因：關鍵因子：生長偏向，主幹斜向，等勢枝，等勢幹，修枝後傷口無法癒合。；處理建議：生長偏向嚴重有影響安全，樹木截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062056', 'pkl:removal_D3BB0AD389D1F53B:0:B223', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
