INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW002KBAV5E0WKA5VVFH', 25.02966, 121.56847, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B130。日期為計畫上網日期。原因：關鍵因子：樹冠受機械危重，大部分偏向，等勢幹，移除枯枝等不健康部位樹型完全崩壞，修枝後復原法癒合產生腐朽。；處理建議：截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022050', 'pkl:removal_D3BB0AD389D1F53B:0:B130', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW002KVVHFGADQXGTMXB', 25.033, 121.5686, '茄苳', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 C181。日期為計畫上網日期。原因：關鍵因子：受機械危害嚴重，面積超過60%樹冠，移除枯枝無法恢復良好樹型，有等勢幹，該樹位於路口遭強修剪致樹型崩壞；處理建議：生長偏向影響安全，樹木截幹後癒合不良有影響結構之虞，建議移除', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY0030551062', 'pkl:removal_D3BB0AD389D1F53B:0:C181', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW002P31YE3WX9RRHTD1', 25.03224, 121.56846, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B189。日期為計畫上網日期。原因：關鍵因子：浮根嚴重，主幹彎曲斜向生長，主枝修枝後無法癒合產生腐朽，枝幹生長交錯凌亂。；處理建議：生長偏向嚴重有影響安全，樹木截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062008', 'pkl:removal_D3BB0AD389D1F53B:0:B189', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
