INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW004KGXN6YPQYR0Q98H', 25.03026, 121.56816, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A85。日期為計畫上網日期。原因：關鍵因子：根領處有損傷，主幹腫大有偏向生長，創傷後無法癒合產生腐朽。；處理建議：根領有損傷影響結構支撐，主幹歪斜或生長偏向，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031114', 'pkl:removal_D3BB0AD389D1F53B:0:A85', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
