INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW005NCQ8MJ2HKXG863Z', 25.02929, 121.5685, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B233。日期為計畫上網日期。原因：關鍵因子：主幹傾斜≦30 度且臨近行道樹，受機械危害嚴明顯，修枝後復原法癒合產生腐朽。；處理建議：生長偏向，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062066', 'pkl:removal_D3BB0AD389D1F53B:0:B233', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
