INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW005RQ2NB3C4A4XX318', 25.03025, 121.56813, '樟樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A151。日期為計畫上網日期。原因：關鍵因子：經儀器測量確認外殼開放度≧50%以上且木質部已腐朽；處理建議：建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680092005', 'pkl:removal_D3BB0AD389D1F53B:0:A151', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW005T6PS2X5FPFBVDEK', 25.09802, 121.54621, '楓香', '[20]', '[]', 3, 5, '計畫移植。臺北捷運環狀線北環段CF690B區段標CF694子標樹木移植計畫書（已核准）。計畫書編號 Y28-114。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：為配合台北捷運環狀線北環段Y27 站(不含),Y28 站,Y29 站,尾軌段及車站間之潛盾隧道,沿線聯絡通道各項施工需求配合辦理樹木之移植及現地保護作業。', 'https://pkl.gov.taipei/News_Content.aspx?n=EADA2FE1CC599432&sms=1A78AA9B70F45574&s=368BF9E235237B1E', '2026-09-23', NULL, 'SL0560211030', 'pkl:transplant_368BF9E235237B1E:0:Y28-114', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW005W02GMJM1AHABZEZ', 25.07305, 121.57936, '烏桕', '[20]', '[]', 3, 5, '計畫移植。臺北捷運環狀線東環段CF720區段標樹木移植計畫（審查中）。計畫書編號 Y33-14。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：既有樹木位於臺北捷運環狀線東環段工程CF721標，包括Y33車站等開挖施工、管線開挖範圍、隧道聯絡通道施工及因施工期間配合交通維持影響範圍等，受施工擾動地面範圍內之既有樹木擬辦理遷移。', 'https://pkl.gov.taipei/News_Content.aspx?n=EADA2FE1CC599432&sms=1A78AA9B70F45574&s=545556494CAD7667', '2026-09-23', NULL, 'NH0815000007', 'pkl:transplant_545556494CAD7667:0:Y33-14', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW005W6YR1E938V8H64R', 25.02998, 121.56813, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A148。日期為計畫上網日期。原因：關鍵因子：樹型生長偏向，樹冠受機械危害，主枝修枝或創傷後癒不良合產生腐朽。；處理建議：生長偏向嚴重有影響安全之虞，截幹後癒合不良，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680092008', 'pkl:removal_D3BB0AD389D1F53B:0:A148', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
