INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW006XWJ856BM92DW1VB', 25.02871, 121.56822, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A116。日期為計畫上網日期。原因：關鍵因子：根領處有腐朽損傷，主幹受機械危害明顯，修枝後切口無法癒合產生腐朽或腫大。；處理建議：根領有損傷影響結構，主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031145', 'pkl:removal_D3BB0AD389D1F53B:0:A116', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
