INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW009G400D6KDJJD1691', 25.0239, 121.56982, '杜英', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 203。日期為計畫上網日期。原因：樹型歪斜主幹傾斜>30 度且臨近園路，樹根領不見，修枝後出現畸形，若移除枯枝等不健康部位無法恢復良好樹型，樹幹有裂紋。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, NULL, 'pkl:removal_D3BB0AD389D1F53B:2:203', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW009GPMD22ZTS5MECHW', 25.03107, 121.56819, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A72。日期為計畫上網日期。座標與計畫書編號 A73 相同，位置可能有誤。原因：關鍵因子：樹形歪斜，等勢幹影響樹勢，修枝後無法癒合產生腐朽。；處理建議：樹木截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031101', 'pkl:removal_D3BB0AD389D1F53B:0:A72', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW009JGNXERATMPYVS2N', 25.03087, 121.56816, '黑板樹', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A76。日期為計畫上網日期。原因：關鍵因子：根領處有鐵線侵入，部分偏向，移除枯枝等不健康部位，樹型完全崩壞。；處理建議：根領有損傷影響結構支撐，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031105', 'pkl:removal_D3BB0AD389D1F53B:0:A76', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
