INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00AFDZZTPDR3W0J1FS', 25.02398, 121.57019, '榕樹', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 253。日期為計畫上網日期。原因：等勢幹，根群出現浮根及盤根，傷口無法癒合發生變色，移除枯枝等不健康部位預期無法恢復良好樹型。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, NULL, 'pkl:removal_D3BB0AD389D1F53B:2:253', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00AGW2A4GPG0FYPKV7', 25.09789, 121.54594, '楓香', '[20]', '[]', 3, 5, '計畫移植。臺北捷運環狀線北環段CF690B區段標CF694子標樹木移植計畫書（已核准）。計畫書編號 Y28-110。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：為配合台北捷運環狀線北環段Y27 站(不含),Y28 站,Y29 站,尾軌段及車站間之潛盾隧道,沿線聯絡通道各項施工需求配合辦理樹木之移植及現地保護作業。', 'https://pkl.gov.taipei/News_Content.aspx?n=EADA2FE1CC599432&sms=1A78AA9B70F45574&s=368BF9E235237B1E', '2026-09-23', NULL, 'SL0560211026', 'pkl:transplant_368BF9E235237B1E:0:Y28-110', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00AH6K6K35PA4CT6SA', 25.02968, 121.56845, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B131。日期為計畫上網日期。原因：關鍵因子：等勢幹，移除枯枝等不健康部位樹型完全崩壞，修枝後復原法癒合產生腐朽。；處理建議：主幹歪斜或生長偏向嚴重有影響安全之虞，修枝後復原癒合不良，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022051', 'pkl:removal_D3BB0AD389D1F53B:0:B131', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
