INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00HTSYNGGC4J85YZGX', 25.0291, 121.5685, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B237。日期為計畫上網日期。原因：關鍵因子：樹幹受機械危害明顯，修枝後無法癒合產生腐朽。根領不見及活冠比差。；處理建議：樹木截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062070', 'pkl:removal_D3BB0AD389D1F53B:0:B237', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00HVG79QJJ2HMWGG61', 25.03236, 121.56816, '樟樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A49。日期為計畫上網日期。座標與計畫書編號 A50 相同，位置可能有誤。原因：關鍵因子：樹冠受機械危害嚴重，排水不良，修剪不當，樹勢衰弱。；處理建議：主幹主枝腐朽影響安全，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680010003', 'pkl:removal_D3BB0AD389D1F53B:0:A49', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00HW5SKMDD4EEW7P86', 25.03223, 121.56816, '樟樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A51。日期為計畫上網日期。原因：關鍵因子：主幹損傷嚴重，修剪不當，覆土過深，樹勢衰弱。；處理建議：明顯樹洞或主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680010005', 'pkl:removal_D3BB0AD389D1F53B:0:A51', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00J0YNAE1PY7SJG9PW', 25.03186, 121.56808, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A190。日期為計畫上網日期。原因：關鍵因子：有等勢枝或等勢幹，修枝後無法癒合產生腐朽照片6，樹冠受機械危害，主幹及分枝有腐朽照片5。；處理建議：有等勢幹，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1560042044', 'pkl:removal_D3BB0AD389D1F53B:0:A190', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
