INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00JWEMT89SAMW978DA', 25.03319, 121.56852, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 C186。日期為計畫上網日期。座標與計畫書編號 C185 相同，位置可能有誤。原因：關鍵因子：劈裂腐朽枝多，修剪後無法再生恢復或出現畸形，傷口無法癒合發生變色。；處理建議：根基或根領有損傷影響結構支撐，明顯樹洞或主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680061114', 'pkl:removal_D3BB0AD389D1F53B:0:C186', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00JWV691M0R7NKGD5X', 25.02936, 121.5685, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B231。日期為計畫上網日期。原因：關鍵因子：等勢幹，活冠比差，樹冠受機械危害，修枝後切口癒合不良。根領不見，根領與主幹相接處有腐朽。；處理建議：領有損傷影響結構，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062064', 'pkl:removal_D3BB0AD389D1F53B:0:B231', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00JXAD8EWQ3JE9BY5W', 25.03126, 121.56847, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B100。日期為計畫上網日期。座標與計畫書編號 B101 相同，位置可能有誤。原因：關鍵因子：盤根狀況嚴重，浮根嚴重，曾截幹修剪，枝條或枝幹有膨脹腐朽癒合不良，修枝或後無法癒合產生腐朽。；處理建議：樹木緊鄰建物或結構物致根球無法形成或挖掘困難，樹木截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022020', 'pkl:removal_D3BB0AD389D1F53B:0:B100', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00K0H030X9E4ZH77FG', 25.07169, 121.57851, '茄苳', '[20]', '[]', 3, 5, '計畫移植。臺北捷運環狀線東環段CF720區段標樹木移植計畫（審查中）。計畫書編號 Y33-127。日期為計畫上網日期。座標依樹籤編號取自公園處清冊。原因：既有樹木位於臺北捷運環狀線東環段工程CF721標，包括Y33車站等開挖施工、管線開挖範圍、隧道聯絡通道施工及因施工期間配合交通維持影響範圍等，受施工擾動地面範圍內之既有樹木擬辦理遷移。', 'https://pkl.gov.taipei/News_Content.aspx?n=EADA2FE1CC599432&sms=1A78AA9B70F45574&s=545556494CAD7667', '2026-09-23', NULL, 'NH0815000139', 'pkl:transplant_545556494CAD7667:0:Y33-127', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
