INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00Q1EB42CRJWCEFD4E', 25.02914, 121.56812, '榕樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A132。日期為計畫上網日期。原因：關鍵因子：主幹有修剪傷口癒合不良，樹型偏向生長，樹形受機械危害明顯，修枝後無法癒合產生腐朽。；處理建議：明顯樹洞或主幹主枝明顯腐朽影響安全，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680092020', 'pkl:removal_D3BB0AD389D1F53B:0:A132', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00Q30023QN8ZPRTZCB', 25.03387, 121.56848, '黑板樹', '[20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 C173。日期為計畫上網日期。原因：關鍵因子：根領處有空洞，有等勢枝或等勢幹，覆土過高，傷口癒合不全。；處理建議：根基或根領有損傷影響結構支撐，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680021119', 'pkl:removal_D3BB0AD389D1F53B:0:C173', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
