INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00S1GGXDERAMVGXTTV', 25.03056, 121.56821, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A82。日期為計畫上網日期。原因：關鍵因子：根領處有空洞深約25 公分，曾斷頭修剪，等勢幹，修枝後切口癒合不良，活冠比差。；處理建議：樹木截幹後癒合不良有影響結構之虞，根領有樹洞影響結構，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031111', 'pkl:removal_D3BB0AD389D1F53B:0:A82', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00S40645MNBQCNJEZ3', 25.02985, 121.56843, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B128。日期為計畫上網日期。原因：關鍵因子：樹冠受機械危重，大部分偏向，等勢幹，修枝後復原法癒合產生腐朽。；處理建議：樹木緊鄰建物或結構物致根球無法形成，截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022048', 'pkl:removal_D3BB0AD389D1F53B:0:B128', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00S4KP2AR36ZCKGQPH', 25.0335, 121.56854, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 C190。日期為計畫上網日期。原因：關鍵因子：有等勢幹，移除枯枝無法恢復良好樹型，修枝或後無法癒合產生腐朽。；處理建議：樹洞或主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680061110', 'pkl:removal_D3BB0AD389D1F53B:0:C190', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00S61RQY00ATKBAHEF', 25.02914, 121.5685, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B236。日期為計畫上網日期。原因：關鍵因子：主幹斜向生長，等勢幹，樹冠受機械危害，修枝後無法癒合，分支創傷傷口癒合不全。；處理建議：主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062069', 'pkl:removal_D3BB0AD389D1F53B:0:B236', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
