INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00WFYDSS45G12JHS1A', 25.03115, 121.56846, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B103。日期為計畫上網日期。原因：關鍵因子：根群損傷，樹勢不佳，枝條或枝幹有膨脹腐朽癒合不良，修枝或後無法癒合產生腐朽。；處理建議：根領有損傷影響結構支撐，樹木緊鄰建物或結構物致根球無法形成，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022023', 'pkl:removal_D3BB0AD389D1F53B:0:B103', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
