INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00ZFAAA6M9T90ZJYR1', 25.03138, 121.5682, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A63。日期為計畫上網日期。原因：關鍵因子：主幹有癒合不全切口不良，修枝後無法癒合產生腐朽，移除枯枝等不健康部預期無法恢復良好樹型。；處理建議：明顯樹洞或主幹主枝明顯腐朽影響安全，主幹有癒合不全切口不良及腐朽，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031092', 'pkl:removal_D3BB0AD389D1F53B:0:A63', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW00ZM30PXS5636TG7NG', 25.02917, 121.5685, '水黃皮', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B235。日期為計畫上網日期。原因：關鍵因子：根領處有損傷，等勢幹，樹冠受機械危害，修枝後傷口無法癒合產生腐朽，枝葉稀疏活冠比低。；處理建議：主幹主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680062068', 'pkl:removal_D3BB0AD389D1F53B:0:B235', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
